    const { value: current, indent } = item;
    if (!isContainer(current)) {
      out.push(JSON.stringify(current));
      continue;
    }
    const keys = Array.isArray(current) ? null : Object.keys(current);
    const [openMark, closeMark] = keys ? ['{', '}'] : ['[', ']'];
