  } catch (err) {
    if (!(err instanceof PatchError)) throw err;
    return fail(`Error: ${err.message}`, 4);
  }
  process.stdout.write(`${stringify(result)}\n`);
  process.exitCode = 0;
}

await main(process.argv.slice(2));

